def get_nth_prime(n):
    """Find the nth prime number"""
    count = 0
    candidate = 2

    while count < n:
        is_prime = True
        for i in range(2, int(candidate ** 0.5) + 1):
            if candidate % i == 0:
                is_prime = False
                break

        if is_prime:
            count += 1
            if count == n:
                return candidate

        candidate += 1

    return candidate

# Find the 50th prime number
