def lennard_jones_potential(r, epsilon, sigma):
    """Calculate Lennard-Jones potential for a given distance"""
    return 4 * epsilon * ((sigma/r)**12 - (sigma/r)**6)

def total_potential_energy(x, y, z, epsilon, sigma):
    """Calculate total potential energy of all particle pairs"""
    n = len(x)
    total_energy = 0

    for i in range(n):
        for j in range(i+1, n):
            # Calculate distance
            r = np.sqrt((x[i]-x[j])**2 + (y[i]-y[j])**2 + (z[i]-z[j])**2)
            # Add potential energy for this pair
            total_energy += lennard_jones_potential(r, epsilon, sigma)

