def sum_of_primes(n):
    """
    Calculate the sum of all prime numbers from 2 to n (inclusive)
    """
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    prime_sum = 0
    primes = []
    for num in range(2, n + 1):
        if is_prime(num):
            prime_sum += num
            primes.append(num)

    return prime_sum, primes

